CREATE TABLE Blockbusters (
    id INTEGER PRIMARY KEY,
    title TEXT,
    releaseYear INTEGER,
    director TEXT,
    budget REAL,
    boxOffice REAL,
    film_festival_id INTEGER,
    FOREIGN KEY(film_festival_id) REFERENCES Festivals(id)
);
