    LitID INTEGER PRIMARY KEY AUTOINCREMENT,
    Title TEXT,
    Synopsis TEXT,
    Language TEXT,
    PublicationYear INT,
    LiteratureType TEXT ,
    AuthorID INTEGER,
    PublisherID INTEGER,
    FOREIGN KEY(AuthorID) REFERENCES Authors(AuthorID),
    FOREIGN KEY(PublisherID) REFERENCES Publishers(PublisherID));
