INSERT INTO "Guests" VALUES(2,'Emily Davis','Author','Laughing Matters',1);
CREATE TABLE Podcasters(
    id INTEGER PRIMARY KEY,
    name TEXT,
    location TEXT,
    years_experience INTEGER
);
