INSERT INTO "Podcasters" VALUES(2,'Jane Doe','Los Angeles',8);
CREATE TABLE Reviews(
    id INTEGER PRIMARY KEY,
    reviewer_name TEXT,
    rating INTEGER ,
    comments TEXT,
    show_id INTEGER,
    review_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(show_id) REFERENCES Shows(id)
);
