INSERT INTO "Reviews" VALUES(2,'Bob White',4,'Funny episodes.',2,'2024-03-07 21:13:47');
CREATE TABLE Shows(
    id INTEGER PRIMARY KEY,
    title TEXT,
    genre TEXT,
    network TEXT,
    audio_format TEXT ,
    host TEXT,
    FOREIGN KEY(host) REFERENCES Podcasters(name)
);
