BEGIN TRANSACTION;
CREATE TABLE Attendance(
    AttendenceID INTEGER PRIMARY KEY AUTOINCREMENT,
    EnrollmentID INT,
    NumberOfDaysPresent INT,
    TotalNumberOfClasses INT,
    ExcusedAbsences INT,
    UnexcusedAbsences INT,
    FOREIGN KEY (EnrollmentID) REFERENCES Enrollment(EnrollmentID));
