INSERT INTO "Attendance" VALUES(2,2,22,25,1,0);
CREATE TABLE Courses(
    CourseID INTEGER PRIMARY KEY AUTOINCREMENT,
    Core_Concepts TEXT,
    Advanced_Topics TEXT,
    CourseName TEXT,
    TeachersName TEXT);
INSERT INTO "Courses" VALUES(1,'Introduction to Math','Calculus and Probability','Math 101','Mr. Johnson');
INSERT INTO "Courses" VALUES(2,'English Literature','Poetry and Fiction','Engl 101','Mrs. Williams');
CREATE TABLE Enrollment(
    EnrollmentID INTEGER PRIMARY KEY AUTOINCREMENT,
    StudentID INT,
    CourseID INT,
    FOREIGN KEY (StudentID) REFERENCES Students(StudentID),
    FOREIGN KEY (CourseID) REFERENCES Courses(CourseID));
CREATE TABLE Grades(
    GradeID INTEGER PRIMARY KEY AUTOINCREMENT,
    EnrollmentID INT,
    Grade CHAR(2),
    Comments TEXT,
    FOREIGN KEY (EnrollmentID) REFERENCES Enrollment(EnrollmentID));
