    FOREIGN KEY (studentId) REFERENCES Students(id),
    FOREIGN KEY (themeTrackId) REFERENCES Theme_Tracks(themeTrackId),
    FOREIGN KEY (projectId) REFERENCES Projects(projectId)
);
