gold_queries:
SELECT PR.score FROM Students AS S JOIN Exams AS E ON S.id = E.studentId JOIN Minimum_Scores AS PR ON E.minScoreId = PR.id WHERE S.firstName = 'Michael' AND S.lastName = 'Brown';

SELECT PR.percentage FROM Students AS S JOIN Exams AS E ON S.id = E.studentId JOIN percentage_requirements AS PR ON E.percentReqId = PR.id WHERE S.firstName = 'Michael' AND S.lastName = 'Brown';

SELECT PR.score, P.percentage FROM Students AS S JOIN Exams AS E ON S.id = E.studentId JOIN Minimum_Scores AS PR ON E.minScoreId = PR.id JOIN percentage_requirements AS P ON E.percentReqId = P.id  WHERE S.firstName = 'Michael' AND S.lastName = 'Brown';

