gold_queries:
SELECT a.Description, d.Year, d.Month, d.Day
FROM Assignments a
JOIN Date d ON a.Due_Date = d.Date_ID;

SELECT a.Description, d.hour, d.minute, d.second 
FROM Assignments a
JOIN Time d ON a.Due_time = d.time_ID;

SELECT a.Description, d.Year, d.Month, d.Day,  t.hour, t.minute, t.second
FROM Assignments a
JOIN Date d ON a.Due_Date = d.Date_ID
JOIN Time t ON a.Due_time = t.time_ID;

