    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    due_date INTEGER,
    due_time INTEGER,
    description TEXT,
    FOREIGN KEY (due_date) REFERENCES Date(date_id),
    FOREIGN KEY (due_time) REFERENCES Time(time_id)
);
