gold_queries:
SELECT milestone_name, description FROM Physical_Milestones JOIN Child_Age ON Child_Age.physical_milestone_id = Physical_Milestones.id JOIN Children ON  Child_Age.child_id = Children.id WHERE name = 'Charlie';

SELECT milestone_name, description FROM Cognitive_Milestones JOIN Child_Age ON Child_Age.cognitive_milestone_id = Cognitive_Milestones.id JOIN Children ON  Child_Age.child_id = Children.id WHERE name = 'Charlie';

SELECT Physical_Milestones.milestone_name, Physical_Milestones.description, Cognitive_Milestones.milestone_name, Cognitive_Milestones.description  FROM Physical_Milestones JOIN Child_Age ON Child_Age.physical_milestone_id = Physical_Milestones.id JOIN Children ON  Child_Age.child_id = Children.id JOIN Cognitive_Milestones ON Child_Age.cognitive_milestone_id = Cognitive_Milestones.id  WHERE name = 'Charlie';

