    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT ,
    title TEXT,
    genre TEXT,
    creator TEXT,
    numEpisodesOrDuration INTEGER,
    premiereMonth INTEGER,
    premiereYear INTEGER,
    season INT DEFAULT 1,
    FOREIGN KEY(creator) REFERENCES Creators(id));
