gold_queries:
SELECT AVG(end_time - start_time) FROM On_Sale_Date JOIN Tickets ON Tickets.ON_SALE_DATE_ID = On_Sale_Date.sale_id WHERE seat_number = "A1";

SELECT AVG(end_time - start_time) FROM Pre_sale_Date JOIN Tickets ON Tickets.Presale_Date_ID = Pre_sale_Date.presale_id WHERE seat_number = "A1";

SELECT AVG(Pre_sale_Date.end_time - Pre_sale_Date.start_time), AVG(On_Sale_Date.end_time - On_Sale_Date.start_time) FROM On_Sale_Date JOIN Tickets ON Tickets.ON_SALE_DATE_ID = On_Sale_Date.sale_id JOIN Pre_sale_Date ON Pre_sale_Date.presale_id = Tickets.Presale_Date_ID WHERE seat_number = "A1";

