SELECT name FROM Producer JOIN Documentary ON Documentary.producer_id =  Producer.id JOIN Movie ON  Movie.foreign_key =  Documentary.id  JOIN Review  On Review.movie_id =  Movie.id ORDER BY rating DESC LIMIT 1;

SELECT name FROM Company JOIN Documentary ON Documentary.Company_id =  Company.id JOIN Movie ON  Movie.foreign_key =  Documentary.id  JOIN Review  On Review.movie_id =  Movie.id ORDER BY rating DESC LIMIT 1;

SELECT Company.name, Producer.name FROM Producer JOIN Documentary ON Documentary.producer_id =  Producer.id JOIN Movie ON  Movie.foreign_key =  Documentary.id  JOIN Review  On Review.movie_id =  Movie.id JOIN Company ON Documentary.Company_id =  Company.id  ORDER BY rating DESC LIMIT 1;

