gold_queries:
SELECT name FROM Producer JOIN Documentary ON Documentary.producer_id =  Producer.id JOIN Movie ON  Movie.foreign_key =  Documentary.id ORDER BY box_office DESC LIMIT 1;

SELECT name FROM Company JOIN Documentary ON Documentary.Company_id =  Company.id JOIN Movie ON  Movie.foreign_key =  Documentary.id ORDER BY box_office DESC LIMIT 1;

SELECT Company.name, Producer.name FROM Producer JOIN Documentary ON Documentary.producer_id =  Producer.id JOIN Movie ON  Movie.foreign_key =  Documentary.id JOIN Company ON Documentary.Company_id =  Company.id ORDER BY box_office DESC LIMIT 1;

