CREATE TABLE bookings (
    id INTEGER PRIMARY KEY,
    userId INTEGER,
    ticketId INTEGER,
    bookingDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status TEXT ,
    FOREIGN KEY(userId) REFERENCES users(id),
    FOREIGN KEY(ticketId) REFERENCES tickets(id)
);
